import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"商店街事務","description":"商店街相關事務的申請及說明。","frontmatter":{"title":"商店街事務","description":"商店街相關事務的申請及說明。"},"headers":[],"relativePath":"apply/form_shop/index.md","filePath":"apply/form_shop.md"}'),t={name:"apply/form_shop/index.md"};function o(s,l,h,n,u,d){return a(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="商店街事務" tabindex="-1">商店街事務 <a class="header-anchor" href="#商店街事務" aria-label="Permalink to &quot;商店街事務&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">公告(2022/07/01)</p><p>由於現在商店街即將進行新舊轉換，網站資訊可能無法及時更新，請以實際情況及Discord公告為主</p></div><h2 id="相關連結" tabindex="-1">相關連結 <a class="header-anchor" href="#相關連結" aria-label="Permalink to &quot;相關連結&quot;">​</a></h2><p><font size="4"><a href="https://ppt.cc/fua0nx" target="_blank" rel="noreferrer">商店街須知</a></font></p><ul><li>請商人及想承租商店的玩家務必詳閱</li></ul><p><font size="4"><a href="https://forms.gle/pPEdJpxtktGR15vs9" target="_blank" rel="noreferrer">商人事務表單</a></font></p><ul><li>擺放商人、調整領地負責人/店面轉讓、新商店承租、繳費、退租，請填寫此表單</li></ul><h2 id="事務說明" tabindex="-1">事務說明 <a class="header-anchor" href="#事務說明" aria-label="Permalink to &quot;事務說明&quot;">​</a></h2><h3 id="擺放商人" tabindex="-1">擺放商人 <a class="header-anchor" href="#擺放商人" aria-label="Permalink to &quot;擺放商人&quot;">​</a></h3><ul><li>擺放商人的工本費(不論是新租/轉讓/續租/增加商人) 統一為500元工本費</li><li>生物不限制種類，唯一條件是&quot;不能太大隻&quot;(例:凋零/終界龍/地獄幽靈)</li></ul><h3 id="調整領地負責人-店面轉讓" tabindex="-1">調整領地負責人 / 店面轉讓 <a class="header-anchor" href="#調整領地負責人-店面轉讓" aria-label="Permalink to &quot;調整領地負責人 / 店面轉讓&quot;">​</a></h3><ul><li>調整領地負責人 <ul><li>就是單純的增加領地負責人，讓他們可以一起幫忙蓋商店 <ul><li>領地負責人不能控制商人及補貨，這只有店長能做</li></ul></li><li>一間店不含店長，最多可有四位領地負責人(1位店長+4位負責人)</li></ul></li><li>店面轉讓 <ul><li>請注意，轉讓是直接更改店長的名字和所有權，同時重置領地負責人</li><li>租金期限與位置皆不變 <ul><li>假設今天是7/10，你的店租到7/30，對方會直接繼續用到7/30後才需要續繳下期租金<br> 中間20天的租金原店主已代繳，這部分由雙方自行協調</li></ul></li><li>轉移本身不用錢 <ul><li>請繼承人之後再填寫問券，並且選擇&quot;擺放商人&quot;的選項，再選擇<b>已繳交500元(放商人)</b></li><li>接著由<b>繼承人</b>繳交500元擺放商人的費用</li></ul></li><li>店面轉讓的申請者(原本持有店面的人) <ul><li><b>在申請完之後，請將你的商人全數刪除</b></li></ul></li></ul></li><li>玩家ID填寫 <ul><li>如果要增加領地負責人 請填寫<br><code>增加領地負責人 olinger99 LeeTiger125</code></li><li>如果要移除領地負責人 請填寫<br><code>移除領地負責人 LeeTiger125</code></li><li>如果要轉讓店面 請填寫<br><code>店面轉讓 RS1 MiunaPA 轉給 olinger99</code></li></ul></li></ul><h3 id="新商店承租" tabindex="-1">新商店承租 <a class="header-anchor" href="#新商店承租" aria-label="Permalink to &quot;新商店承租&quot;">​</a></h3><ul><li>首先，<b>詳閱商店街須知</b>：<a href="https://ppt.cc/fua0nx" target="_blank" rel="noreferrer">https://ppt.cc/fua0nx</a></li><li>再來，去Discord<a href="/discord/text_channel/">商店街交易</a>頻道及<a href="https://docs.google.com/spreadsheets/d/1EOSqqmGlefJVZIuRV3W1OmF0qTZSLE-6tkApxXY9iPg/edit?usp=sharing" target="_blank" rel="noreferrer">商店列表</a>確認有無空店面開放承租</li><li>確認有店面開放承租後即可填寫<a href="https://forms.gle/pPEdJpxtktGR15vs9" target="_blank" rel="noreferrer">商人事務表單</a>選擇<b>新商店承租</b>，並按照指示填寫表單 <ul><li><font color="red"><b>現階段請不要繳費</b></font>，管理員會依照表單送出的時間先後審核，通過後才會在Discord通知繳費</li></ul></li><li>最後，當收到繳費通知時即代表你承租成功，接下來依照管理員指示完成繳費及商人設定即完成承租手續 <ul><li>請務必在管理員給的期限內完成繳費，逾期將會將商店讓給其他玩家承租</li></ul></li></ul><p><b>支付租金的指令<code>/money pay shop 租金</code></b><br><img src="https://i.imgur.com/YbZC9Zb.png" style="width:40%;"></p><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h3><ul><li>請務必按照說明進行準備，以加快同步作業 <ul><li>未按照說明處理畫作有可能會被退件，屆時請重新申請</li></ul></li><li>店面轉讓僅受理一次，若要再次轉讓僅可辦理退租 <ul><li>例：若你的店面是從別的玩家那邊轉讓過來的，要再次轉讓只能申請退租</li></ul></li><li>商店承租後，每個月須定時繳納租金，嚴重逾期者會強制撤租，將空位讓給其他玩家承租 <ul><li>確切日期請依管理員在Discord的通知為主</li><li>店面遭強制撤租後會移地保管，屆時須支付罰金才可贖回店面 <ul><li>確切金額請在Discord<a href="/discord/text_channel/">商店街交易</a>頻道詢問管理員</li></ul></li></ul></li><li>若伺服方和商店店長解除遊玩契約，店面將會由伺服方強制銷毀 <ul><li>屆時任何玩家都不能承接店面資產(包含領地負責人也是)</li></ul></li><li>申請作業需一定時間，請玩家耐心等候處理</li></ul><h2 id="商店街資訊" tabindex="-1">商店街資訊 <a class="header-anchor" href="#商店街資訊" aria-label="Permalink to &quot;商店街資訊&quot;">​</a></h2><h3 id="商店列表" tabindex="-1"><a href="https://docs.google.com/spreadsheets/d/1EOSqqmGlefJVZIuRV3W1OmF0qTZSLE-6tkApxXY9iPg/edit?usp=sharing" target="_blank" rel="noreferrer">商店列表</a> <a class="header-anchor" href="#商店列表" aria-label="Permalink to &quot;[商店列表](https://docs.google.com/spreadsheets/d/1EOSqqmGlefJVZIuRV3W1OmF0qTZSLE-6tkApxXY9iPg/edit?usp=sharing)&quot;">​</a></h3><h3 id="商店街平面圖" tabindex="-1">商店街平面圖 <a class="header-anchor" href="#商店街平面圖" aria-label="Permalink to &quot;商店街平面圖&quot;">​</a></h3><img src="https://i.imgur.com/fvF2oYY.jpg" style="width:100%;">',21)])])}const f=e(t,[["render",o]]);export{p as __pageData,f as default};
